import { Order, OrderItem, createOrder } from '../domain/Order';
import { Catalog } from '../domain/Catalog';
import { OrderRepository } from '../domain/OrderRepository';

export interface PlaceOrderRequest {
  customerId: string;
  items: OrderItem[];
}

export class PlaceOrderUseCase {
  constructor(private catalog: Catalog, private orderRepository: OrderRepository) {}

  execute(request: PlaceOrderRequest): Order {
    // Validate stock for all items
    for (const item of request.items) {
      if (!this.catalog.getProduct(item.productId)) {
        throw new Error(`Product ${item.productId} not found`);
      }
      if (!this.catalog.canReserve(item.productId, item.quantity)) {
        throw new Error(`Insufficient stock for product ${item.productId}`);
      }
    }

    // Reserve stock for all items
    for (const item of request.items) {
      this.catalog.reserve(item.productId, item.quantity);
    }

    // Create and save order
    const orderId = `order-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const order = createOrder(orderId, request.customerId, request.items);
    this.orderRepository.save(order);

    return order;
  }
}

